"""LanceDB-backed implementation.

All LanceDB specifics — the embedded table, hybrid query syntax, the native FTS
index, predicate building — live here, behind the generic store interface.

``lancedb`` is imported lazily so this module stays importable without it.
"""

from typing import Any, Dict, List, Optional

import numpy as np
import structlog

from rasa.builder.document_retrieval.local.vector_store import BaseVectorStore, StoreHit

structlogger = structlog.get_logger()

_TABLE_NAME = "chunks"


class LanceDBVectorStore(BaseVectorStore):
    """Stores chunk records in an embedded LanceDB table on disk."""

    def __init__(self, location: str, table_name: str = _TABLE_NAME) -> None:
        self._location = location
        self._table_name = table_name
        self._table: Any = None  # opened lazily, cached

    def _connect(self) -> Any:
        import lancedb

        return lancedb.connect(self._location)

    def _table_handle(self) -> Any:
        if self._table is None:
            self._table = self._connect().open_table(self._table_name)
        return self._table

    def exists(self) -> bool:
        return self._table_name in self._connect().table_names()

    def add(self, records: List[Dict[str, Any]]) -> None:
        if not records:
            return
        db = self._connect()
        if self._table_name in db.table_names():
            db.open_table(self._table_name).add(records)
        else:
            db.create_table(self._table_name, data=records)
        self._table = None  # invalidate cached handle

    def drop(self) -> None:
        db = self._connect()
        if self._table_name in db.table_names():
            db.drop_table(self._table_name)
        self._table = None

    def ensure_text_index(self) -> None:
        # Native FTS. Best-effort: vector search still works if
        # this fails, only hybrid is unavailable.
        try:
            self._table_handle().create_fts_index(
                "text", replace=True, use_tantivy=False
            )
        except Exception as e:
            structlogger.warning(
                "lancedb_store.fts_index_failed",
                event_info="Full-text index not created; hybrid search unavailable.",
                error=str(e),
            )

    def search(
        self,
        *,
        query_vector: np.ndarray,
        query_text: Optional[str] = None,
        top_k: int,
        hybrid: bool = False,
        where: Optional[str] = None,
    ) -> List[StoreHit]:
        table = self._table_handle()
        if hybrid and query_text is not None:
            # Hybrid: supply both sides explicitly so LanceDB needs no registered
            # embedding function — vector for semantic, text for the FTS/BM25 half.
            search = (
                table.search(query_type="hybrid").vector(query_vector).text(query_text)
            )
        else:
            search = table.search(query_vector)
        # Pre-filter: scope before searching so result count is preserved and the
        # search space actually shrinks.
        if where:
            search = search.where(where, prefilter=True)
        rows = search.limit(top_k).to_list()
        return [self._row_to_hit(row) for row in rows]

    @staticmethod
    def _row_to_hit(row: Dict[str, Any]) -> StoreHit:
        return StoreHit(
            content=row.get("text", ""),
            doc_id=row.get("doc_id"),
            url=row.get("url"),
            title=row.get("title"),
            topic=row.get("topic"),
            chunk_index=row.get("chunk_index"),
            score=row.get("_distance", row.get("_relevance_score")),
        )
